import React, { useState, useEffect } from 'react';
import { db } from '../data/db';
import { useLiveQuery } from "dexie-react-hooks";

export const FormularioPreventa = () => {
  const [formData, setFormData] = useState({ cliente: '', producto: '', cantidad: 1 });
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [sincronizando, setSincronizando] = useState(false);
  const [pedidosEnServidor, setPedidosEnServidor] = useState([]);

  const pedidosLocales = useLiveQuery(() => db.pedidos.toArray());

  // Función para que la Lap vea lo que hay en el servidor
  const consultarServidor = async () => {
    try {
      const res = await fetch('http://192.168.1.221:3001/api/pedidos');
      const data = await res.json();
      setPedidosEnServidor(data);
    } catch (e) { console.log("Servidor no disponible"); }
  };

  useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    
    // Auto-refrescar la lista en la lap cada 5 segundos
    const intervalo = setInterval(consultarServidor, 5000);
    
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
      clearInterval(intervalo);
    };
  }, []);

  const guardarLocal = async (e) => {
    e.preventDefault();
    await db.pedidos.add({ ...formData, fecha: new Date().toISOString(), sincronizado: 0 });
    setFormData({ cliente: '', producto: '', cantidad: 1 });
    alert("✔ Guardado en el cel");
  };

  const enviarALaLap = async () => {
    setSincronizando(true);
    const pendientes = await db.pedidos.where('sincronizado').equals(0).toArray();
    for (const p of pendientes) {
      try {
        const res = await fetch('http://192.168.1.221:3001/api/pedidos', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(p)
        });
        if (res.ok) await db.pedidos.update(p.id, { sincronizado: 1 });
      } catch (e) { break; }
    }
    setSincronizando(false);
    consultarServidor();
  };

  return (
    <div style={{ padding: '20px', maxWidth: '600px', margin: 'auto', fontFamily: 'sans-serif' }}>
      <div style={{ background: isOnline ? '#d4edda' : '#f8d7da', padding: '10px', textAlign: 'center', borderRadius: '5px' }}>
        {isOnline ? '🟢 MODO ONLINE' : '🔴 MODO OFFLINE'}
      </div>
      
      {/* SECCIÓN 1: FORMULARIO */}
      <form onSubmit={guardarLocal} style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '20px' }}>
        <input style={{ padding: '12px' }} type="text" placeholder="Cliente" value={formData.cliente} onChange={e => setFormData({...formData, cliente: e.target.value})} required />
        <input style={{ padding: '12px' }} type="text" placeholder="Producto" value={formData.producto} onChange={e => setFormData({...formData, producto: e.target.value})} required />
        <button type="submit" style={{ padding: '15px', background: '#28a745', color: 'white', fontWeight: 'bold', border: 'none' }}>GUARDAR EN CELULAR</button>
      </form>

      <button onClick={enviarALaLap} style={{ marginTop: '10px', width: '100%', padding: '15px', background: '#007bff', color: 'white', border: 'none' }}>
        {sincronizando ? 'SINCRONIZANDO...' : 'SINCRONIZAR CON LAPTOP'}
      </button>

      {/* SECCIÓN 2: LO QUE HAY EN EL CELULAR */}
      <div style={{ marginTop: '30px' }}>
        <h4>📦 Historial en este dispositivo:</h4>
        {pedidosLocales?.map(p => (
          <div key={p.id} style={{ fontSize: '14px', borderBottom: '1px solid #eee', padding: '5px', display: 'flex', justifyContent: 'space-between' }}>
            <span>{p.cliente} - {p.producto}</span>
            <span>{p.sincronizado ? '✅' : '⏳'}</span>
          </div>
        ))}
      </div>

      {/* SECCIÓN 3: LO QUE LLEGÓ AL SERVIDOR (Solo se verá útil en la Lap) */}
      <div style={{ marginTop: '30px', background: '#e9ecef', padding: '15px', borderRadius: '10px' }}>
        <h4>🖥️ Panel Central (Recibido en Laptop):</h4>
        {pedidosEnServidor.length === 0 ? <p>Esperando datos...</p> : 
          pedidosEnServidor.map((p, i) => (
            <div key={i} style={{ background: 'white', margin: '5px 0', padding: '10px', borderRadius: '5px', borderLeft: '5px solid #007bff' }}>
              <strong>{p.cliente}</strong> compró <strong>{p.producto}</strong>
            </div>
          ))
        }
      </div>
    </div>
  );
};
